mapper.select:
SELECT o.order_id, o.order_type, s.name as store_name, o.status, CASE WHEN o.status = 'PENDING' THEN '주문 접수 대기중' WHEN o.status = 'CONFIRMED' THEN '주문 확인됨' WHEN o.status = 'PREPARING' THEN '음식 준비중' WHEN o.status = 'DELIVERING' THEN '배달중' WHEN o.status = 'DELIVERED' THEN '배달 완료' WHEN o.status = 'CANCELLED' THEN '주문 취소됨' ELSE '확인 중' END as status_description, o.total_amount, (SELECT COUNT(*) FROM tb_order_items WHERE order_id = o.order_id) as item_count, o.created_datetime, CASE WHEN o.status = 'PENDING' THEN '주문 접수 대기중' WHEN o.status = 'CONFIRMED' THEN '30분 - 40분' WHEN o.status = 'PREPARING' THEN '20분 - 30분' WHEN o.status = 'DELIVERING' THEN '10분 - 15분' WHEN o.status = 'DELIVERED' THEN '배달 완료' WHEN o.status = 'CANCELLED' THEN '주문 취소됨' ELSE '확인 중' END as estimated_time FROM tb_order o JOIN tb_store s ON o.store_id = s.id WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.created_datetime DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM tb_order
WHERE user_id = #{userId}

    AND status = #{status}
